export const defaults={version:1,base:40,step:20,cap:200,bonusEvery:4,bonus:100,recoveryNegatives:2,ladderUnlock:16};
export function evaluate(s,outcome,cfg=defaults){let state={...s};if(outcome==='excused')return{state,amount:0,bonus:0};if(outcome!=='negative'){if(state.preResetLevel==null)state.preResetLevel=state.level;state.level=1;state.streak=0;state.negSinceReset=0;return{state,amount:0,bonus:0}}if(state.preResetLevel!=null&&state.negSinceReset===cfg.recoveryNegatives){state.level=state.preResetLevel;state.preResetLevel=null}const amount=Math.min(cfg.base+cfg.step*(state.level-1),cfg.cap);state.streak++;state.negSinceReset++;const bonus=state.streak%cfg.bonusEvery===0?cfg.bonus:0;state.level++;return{state,amount,bonus}}
export function outcomeFor(panels,targets,temperatureOk,adulterated){if(!temperatureOk||adulterated)return'positive';if(targets.some(t=>panels[t]==='invalid'))return'invalid';return targets.every(t=>panels[t]==='negative')?'negative':'positive'}
